    error: 'NO_LINES',
  });
});

test('removeLine rejects non-draft invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
