    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.deepEqual(removeLine(r1.value, 'DEV-HOUR'), {
    ok: false,
    error: 'NO_LINES',
  });
