  assert.equal(r2.value.lines[1].sku, 'DES-HOUR');
  assert.equal(r2.value.lines[1].qty, 5);
});

test('issueInvoice uses existing numbers to avoid duplicates', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const existingNumbers = ['INV-2026-0001', 'INV-2026-0002'];
  const r2 = issueInvoice(r1.value, existingNumbers);

  assert.equal(r2.value.number, 'INV-2026-0003');
});

test('issueInvoice starts fresh for a new year', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2027-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const existingNumbers = ['INV-2026-0001', 'INV-2026-0002', 'INV-2026-0003'];
  const r2 = issueInvoice(r1.value, existingNumbers);

  assert.equal(r2.value.number, 'INV-2027-0001');
});

test('issueInvoice rejects non-draft invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedInvoice = { ...r1.value, status: 'issued', number: 'INV-2026-0001' };

  assert.deepEqual(issueInvoice(issuedInvoice, []), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('issueInvoice does not mutate the input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const invoiceCopy = JSON.parse(JSON.stringify(r1.value));

  issueInvoice(r1.value, []);

  assert.deepEqual(r1.value, invoiceCopy);
});

test('issueInvoice does not mutate line objects', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const originalLine = r1.value.lines[0];
  const originalLineCopy = JSON.parse(JSON.stringify(originalLine));

  const r2 = issueInvoice(r1.value, []);

  assert.deepEqual(originalLine, originalLineCopy);
  assert.notEqual(r2.value.lines[0], originalLine);
});
